package com.agrolink.service.impl;import com.agrolink.dto.address.AddressResponse;import com.agrolink.dto.order.*;import com.agrolink.dto.product.*;import com.agrolink.dto.review.*;import com.agrolink.dto.user.*;import com.agrolink.entity.*;import com.agrolink.enums.ProductStatus;import com.agrolink.repository.*;import com.agrolink.service.*;import org.springframework.stereotype.Service;import java.math.*;import java.util.*;
@Service public class AdminServiceImpl implements AdminService{private final OrderRepository o;private final ReviewService r;private final ReviewRepository rr;private final UserRepository u;private final ProductRepository p;public AdminServiceImpl(OrderRepository o,ReviewService r,ReviewRepository rr,UserRepository u,ProductRepository p){this.o=o;this.r=r;this.rr=rr;this.u=u;this.p=p;}public List<OrderResponse> orders(){return o.findAll().stream().sorted(Comparator.comparing(Order::getId).reversed()).map(this::to).toList();}public OrderResponse updateOrder(Long id,String status){Order x=o.findById(id).orElseThrow(()->new RuntimeException("Order not found"));x.setStatus(com.agrolink.enums.OrderStatus.valueOf(status.toUpperCase()));x=o.save(x);return to(x);}public List<ReviewResponse> reviews(){return rr.findAll().stream().sorted(Comparator.comparing(Review::getId).reversed()).map(x->new ReviewResponse(x.getId(),x.getProduct().getId(),x.getProduct().getName(),x.getBuyer().getFullName(),x.getRating(),x.getComment(),x.getStatus().name())).toList();}public ReviewResponse moderateReview(Long id,String status){return r.moderate(id,status);}public List<UserResponse> users(){return u.findAll().stream().sorted(Comparator.comparing(User::getId).reversed()).map(x->new UserResponse(x.getId(),x.getFullName(),x.getEmail(),x.getRole().name(),x.isEnabled())).toList();}public UserResponse setUserEnabled(Long id,boolean enabled){User x=u.findById(id).orElseThrow(()->new RuntimeException("User not found"));x.setEnabled(enabled);x=u.save(x);return new UserResponse(x.getId(),x.getFullName(),x.getEmail(),x.getRole().name(),x.isEnabled());}public List<ProductResponse> products(){return p.findAll().stream().sorted(Comparator.comparing(Product::getId).reversed()).map(this::toP).toList();}public ProductResponse setProductStatus(Long id,String status){Product x=p.findById(id).orElseThrow(()->new RuntimeException("Product not found"));x.setStatus(ProductStatus.valueOf(status.toUpperCase()));x=p.save(x);return toP(x);}public Map<String,Long> stats(){return Map.of("users",u.count(),"products",p.count(),"orders",o.count(),"reviews",rr.count());}private OrderResponse to(Order x){AddressResponse addr=x.getShippingAddress()==null?null:new AddressResponse(x.getShippingAddress().getId(),x.getShippingAddress().getAddressLine(),x.getShippingAddress().getVillage(),x.getShippingAddress().getCity(),x.getShippingAddress().getDistrict(),x.getShippingAddress().getState(),x.getShippingAddress().getPincode(),x.getShippingAddress().getAddressType(),x.getShippingAddress().getLatitude(),x.getShippingAddress().getLongitude());String front=switch(x.getStatus().name()){case "PLACED"->"PENDING";case "PACKED"->"PROCESSING";case "SHIPPED"->"READY_FOR_SHIPMENT";case "OUT_FOR_DELIVERY"->"IN_TRANSIT";default->x.getStatus().name();};return new OrderResponse(x.getId(),String.format("AGL-2026-%05d",x.getId()),front,x.getTotalAmount(),BigDecimal.ZERO,x.getShippingAddress()==null?null:x.getShippingAddress().getId(),x.getBuyer().getFullName(),x.getBuyer().getEmail(),"PENDING","UPI",x.getCreatedAt()==null?null:x.getCreatedAt().toString(),addr,x.getItems().stream().map(i->new OrderItemResponse(i.getProduct().getId(),i.getProduct().getName(),i.getQuantity(),i.getUnitPrice(),i.getLineTotal(),i.getProduct().getUnit())).toList());}private ProductResponse toP(Product x){return new ProductResponse(x.getId(),x.getSeller().getId(),x.getSeller().getFullName(),x.getCategory().getId(),x.getCategory().getName(),x.getName(),x.getDescription(),x.getPrice(),x.getUnit(),x.getAvailableQuantity(),x.getImageUrl(),x.getLocation(),x.getLatitude(),x.getLongitude(),x.getStatus().name(),x.getSeller().getRole().name());}}